import {OFFERS,CONSULTING,OFFER_TERMS,PRODUCTION_MODES} from './offer-catalog.js';
const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),date=n=>new Date(n).toLocaleDateString('pt-BR');
const labels={offered:'Proposta para aprovação',accepted:'Aceite registrado',active:'Ativo',pending:'Aguardando autorização',delivered:'Entregue',void:'Sem cobrança',declined:'Recusado',review:'Planejamento para aprovar',approved:'Planejamento aprovado',producing:'Produção iniciada'};
export function createCommerceUI({api,esc,getState,openDialog,closeDialog,toast}){
 let active=false,admin=false,org='',data,ticket=0;
 const url=()=>'/api/portal/commerce?org='+encodeURIComponent(org)+'&admin='+(admin?'1':'0');
 const send=d=>api(url(),'POST',d);
 const button=(name,action,id='')=>`<button class="p-button secondary" type="button" data-commerce="${action}" data-id="${esc(id)}">${name}</button>`;
 const field=(name,label,type='text',value='')=>`<label class="p-field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" required></label>`;
 const area=(name,label,value='')=>`<label class="p-field"><span>${label}</span><textarea name="${name}" required>${esc(value)}</textarea></label>`;
 const confirm=label=>`<label class="checkline"><input type="checkbox" required> ${label}</label>`;
 function page(isAdmin=false){admin=isAdmin;org=(admin?new URLSearchParams(location.hash.split('?')[1]||'').get('org'):null)||getState().company.id;return `<section class="page-heading"><div><p class="overline">${admin?'ADMINISTRAÇÃO':'MINHA EMPRESA'}</p><h1>${admin?'Planos e produção':'Meu plano e produção'}</h1><p>Calendário do mês, produção sob demanda e extras autorizados antes de gerar.</p></div></section><div id="commerce-area">Carregando…</div>`;}
 async function load(){const t=++ticket;try{const result=await api(url());if(!active||t!==ticket)return;data=result;render();}catch(e){if(active&&t===ticket)document.querySelector('#commerce-area').innerHTML='<p role="alert">'+esc(e.message)+'</p>'+button('Atualizar','reload');}}
 function render(){const s=data.subscription;document.querySelector('#commerce-area').innerHTML=
  (data.administrativeAccess?`<aside class="admin-callout"><strong>Acesso liberado pela Helpu · ${data.administrativeAccess.purpose==='own'?'uso próprio':'teste'}</strong><p>Sem franquia interna${data.administrativeAccess.end?' até '+new Date(data.administrativeAccess.end).toLocaleDateString('pt-BR'):''}. Esta liberação não é um pagamento.</p></aside>`:'')+(admin?`<label class="p-field"><span>Empresa atendida</span><select id="commerce-org">${data.clients.map(c=>`<option value="${esc(c.id)}" ${org===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`:'')+
  `<div class="commerce-grid">${Object.values(OFFERS).map(o=>`<article class="finance-panel"><h2>${esc(o.name)}</h2><h3>${money(o.priceCents)}/mês</h3><p>8 imagens + 4 vídeos de até 30s.</p><p>${esc(o.publishing)}. Uma rodada de ajustes por entrega.</p><p>Configuração inicial da marca e calendário incluída.</p>${admin?button('Oferecer plano','offer',o.id):''}</article>`).join('')}</div><details class="finance-panel"><summary>Entregas e condições</summary><p>${esc(OFFER_TERMS)}</p><p>Carrosséis são extras independentes do saldo de imagens. Os horários do planejamento aparecem no fuso deste navegador.</p></details>`+
  `<section class="finance-panel"><h2>${s?esc(OFFERS[s.plan].name):'Nenhum plano contratado'}</h2>${s?`<p>${esc(labels[s.state])} · ${date(s.start)} a ${date(s.end)}${s.state==='active'&&!data.active?' · Fora do período contratado':''}</p><p>${esc(s.conditions)}</p>${!admin&&s.state==='offered'?button('Revisar e aceitar','accept_plan'):''}${admin&&s.state==='accepted'?button('Ativar após pagamento','activate'):''}${data.administrativeAccess?'<p>Criações deste acesso liberado não descontam a franquia do plano.</p>':`<div class="commerce-grid"><h3>${data.remaining.image} de 8 imagens disponíveis</h3><h3>${data.remaining.video} de 4 vídeos disponíveis</h3></div>`}<p>Aprovado e consumido: ${data.consumed?.image||0} imagem(ns) e ${data.consumed?.video||0} vídeo(s). Reservado para produção/aprovação: ${data.reserved?.image||0} imagem(ns) e ${data.reserved?.video||0} vídeo(s). A reserva reduz a capacidade disponível, mas o débito só ocorre após aprovar. Falhas técnicas liberam a reserva.</p><label class="p-field"><span>Modo de produção</span><select id="commerce-mode">${Object.entries(PRODUCTION_MODES).map(([id,name])=>`<option value="${id}" ${s.mode===id?'selected':''}>${name}</option>`).join('')}</select></label>${data.active?button('Preparar calendário do mês','plan')+(!admin?' <a class="p-button primary" href="#/create">Criar sob demanda</a>':''):''}`:'<p>A equipe informa período e condições antes do aceite e da ativação.</p>'}</section>`+
  `<section class="finance-panel"><h2>Extras</h2><table class="commerce-table"><thead><tr><th>Entrega</th><th>Essencial</th><th>Assistido</th></tr></thead><tbody>${[['image','Imagem'],['carousel','Carrossel até 5 páginas'],['video','Vídeo até 30s'],['adaptation','Adaptação de formato']].map(([key,title])=>`<tr><td>${title}</td><td>${money(OFFERS.essential.extras[key])}</td><td>${money(OFFERS.assisted.extras[key])}</td></tr>`).join('')}</tbody></table><p>Extras entregues ainda não faturados: <strong>${money(data.extrasCents)}</strong>${s?' · Próxima mensalidade + esses extras: '+money(s.priceCents+data.extrasCents):''}.</p><p>Orçamento pendente não é cobrança. Uma rodada de ajustes incluída; falhas técnicas não são cobradas.</p>${admin?button('Fechar cobrança de extras','invoice_extras'):data.active&&s&&!data.administrativeAccess?button('Solicitar adaptação de formato','adaptation'):''}${data.quotes.map(q=>`<article class="commerce-item"><p>${esc(q.description)}</p><strong>${money(q.priceCents)}</strong> · ${esc(labels[q.state]||q.state)}${q.invoiceId?' · Faturado':''}${!admin&&q.state==='pending'?'<div class="finance-actions">'+button('Revisar preço e autorizar','accept_extra',q.id)+button('Recusar','decline_extra',q.id)+'</div>':''}</article>`).join('')||'<p>Nenhum extra solicitado.</p>'}</section>`+
  `<section class="finance-panel"><h2>Planejamentos</h2>${data.plans.map(p=>`<article class="commerce-item"><h3>${esc(labels[p.state])}</h3><ol>${p.items.map(i=>`<li><strong>${i.format==='reels'?'Vídeo':'Imagem'}</strong> · ${new Date(i.publishAt).toLocaleString('pt-BR')}<p>${esc(i.prompt)}</p>${i.creationId?'<p>Pedido registrado. Confira a prévia na Biblioteca.</p>':''}${i.error?'<p role="alert">'+esc(i.error)+'</p>':''}</li>`).join('')}</ol>${!admin&&p.state==='review'?button('Aprovar planejamento','approve_plan',p.id):''}${['approved','producing'].includes(p.state)?button('Produzir itens pendentes','produce_plan',p.id):''}</article>`).join('')||'<p>Planeje o mês inteiro ou reserve parte do saldo para novidades.</p>'}${!admin?'<a href="#/calendar">Abrir Calendário</a> · <a href="#/studio">Abrir Biblioteca</a>':''}</section>`+
  `<section class="finance-panel"><h2>${esc(CONSULTING.name)} · ${money(CONSULTING.priceCents)}</h2><p>Pagamento único. ${esc(CONSULTING.description)}</p><a class="p-button secondary" href="${admin?'#/consultations-admin':'#/consultations'}">${admin?'Gerenciar consultorias':'Solicitar consultoria'}</a></section>`;}
 function form(title,html,submit){openDialog(title,`<form id="commerce-form">${html}<button class="p-button primary">Confirmar</button><p id="commerce-error" role="alert"></p></form>`,true);const el=document.querySelector('#commerce-form');el.addEventListener('submit',async e=>{e.preventDefault();const b=el.querySelector('button');b.disabled=true;try{const next=await submit(new FormData(el));closeDialog();await load();if(typeof next==='function')next();else toast('Informações atualizadas.');}catch(err){el.querySelector('#commerce-error').textContent=err.message;}finally{b.disabled=false;}});}
 function planning(){form('Preparar planejamento',area('brief','Objetivo e informações confirmadas da campanha')+field('images','Quantidade de imagens (0 a 8)','number',data.subscription.mode==='mixed'?6:8)+field('videos','Quantidade de vídeos (0 a 4)','number',data.subscription.mode==='mixed'?3:4)+field('start','Primeira data sugerida','date',new Date(Math.max(Date.now(),data.subscription.start)).toISOString().slice(0,10)),input=>{const n=Number(input.get('images')),v=Number(input.get('videos'));if(!Number.isInteger(n)||!Number.isInteger(v)||n<0||v<0||n>8||v>4||n+v<1)throw new Error('Escolha até oito imagens e quatro vídeos.');const start=Date.parse(input.get('start')+'T12:00:00-03:00');const items=Array.from({length:n+v},(_,i)=>({format:i<n?'feed':'reels',prompt:String(input.get('brief'))+' — '+['Apresentação','Benefício principal','Dúvida frequente','Como funciona','Aplicação prática','Convite para contato'][i%6],publishAt:new Date(start+Math.max(0,data.subscription.end-start-86400000)*i/Math.max(1,n+v-1)).toISOString()}));return ()=>editPlan(items);});}
 function editPlan(items){form('Revisar temas e datas',`<p>Revise antes de solicitar a aprovação. Legendas e arquivos serão criados na produção.</p>${items.map((i,n)=>`<fieldset><legend>${n+1} · ${i.format==='reels'?'Vídeo':'Imagem'}</legend>${area('prompt'+n,'Briefing',i.prompt)}${field('date'+n,'Data e hora sugeridas','datetime-local',new Date(Date.parse(i.publishAt)-new Date(i.publishAt).getTimezoneOffset()*60000).toISOString().slice(0,16))}${i.format==='reels'?`<label class="p-field"><span>Duração</span><select name="duration${n}"><option value="15">15 segundos</option><option value="30">30 segundos</option></select></label>`:''}<label class="p-field"><span>Materiais da Biblioteca</span><select multiple name="assets${n}">${data.assets.filter(a=>a.mime.startsWith('image/')||i.format==='reels'&&a.mime==='video/mp4').map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></label></fieldset>`).join('')}`,input=>send({action:'save_plan',items:items.map((i,n)=>({...i,prompt:input.get('prompt'+n),publishAt:new Date(input.get('date'+n)).toISOString(),duration:Number(input.get('duration'+n)||15),attachments:input.getAll('assets'+n)}))}));}
 document.addEventListener('click',async e=>{const el=e.target.closest('[data-commerce]');if(!el||!active)return;const action=el.dataset.commerce,id=el.dataset.id,s=data.subscription;try{
  if(action==='reload')return load();if(action==='plan')return planning();
  if(action==='offer')return form('Oferecer '+OFFERS[id].name,field('start','Início do período','date')+field('end','Fim do período (exclusivo)','date')+area('conditions','Condições de renovação, cancelamento e saldo não usado')+'<p>'+esc(OFFER_TERMS)+'</p>',d=>send({action,plan:id,start:d.get('start')+'T00:00:00-03:00',end:d.get('end')+'T00:00:00-03:00',conditions:d.get('conditions')}));
  if(action==='accept_plan')return form('Revisar contratação',`<h2>${money(s.priceCents)}/mês</h2><p>${date(s.start)} a ${date(s.end)}</p><p>${esc(s.terms)}</p><p>${esc(s.conditions)}</p>`+confirm('Li e aceito o preço, período e condições.'),()=>send({action,version:s.version,confirmed:true}));
  if(action==='activate'){const ledger=await api('/api/portal/finance?admin=1&org='+encodeURIComponent(org));return form('Ativar período pago',`<label class="p-field"><span>Pagamento conferido</span><select name="paymentId" required><option value="">Selecione um recebimento</option>${ledger.receivables.filter(r=>r.orgId===org&&r.state==='paid'&&r.providerMode!=='test').map(r=>`<option value="${esc(r.id)}">${esc(r.description)} · ${money(r.amountCents)}</option>`).join('')}</select></label><p>Registre o recebimento no Financeiro antes de ativar.</p>`,d=>send({action,paymentId:d.get('paymentId')}));}
  if(action==='accept_extra'){const q=data.quotes.find(x=>x.id===id),pending=data.quotes.filter(x=>['accepted','delivered'].includes(x.state)&&!x.invoiceId).reduce((n,x)=>n+x.priceCents,0);return form('Autorizar extra',`<p>${esc(q.description)}</p><h2>${money(q.priceCents)}</h2><p>Previsão da próxima cobrança: ${money(s.priceCents+pending+q.priceCents)}, com mensalidade e extras autorizados. Falhas técnicas não serão cobradas.</p><p>Uma rodada de ajustes incluída.</p>`+confirm('Autorizo o valor adicional e a produção.'),()=>send({action,id,priceCents:q.priceCents,confirmed:true}));}
  if(action==='adaptation'){const library=await api('/api/portal/'+org+'/creations');return form('Adaptar arte aprovada',`<p>R$29 por adaptação, preservando o conceito. Você autorizará o orçamento antes da produção.</p><label class="p-field"><span>Arte aprovada</span><select name="creationId" required>${library.creations.filter(c=>c.status==='complete'&&c.review==='approved'&&['feed','story'].includes(c.format)).map(c=>`<option value="${esc(c.id)}">${esc(c.prompt.slice(0,80))} (${c.format})</option>`).join('')}</select></label><label class="p-field"><span>Novo formato</span><select name="format"><option value="story">Story</option><option value="feed">Feed</option></select></label>`,d=>send({action,creationId:d.get('creationId'),format:d.get('format')}));}
  if(action==='invoice_extras')return form('Fechar cobrança',field('competence','Competência','month')+field('dueDate','Vencimento acordado','date')+`<label class="checkline"><input type="checkbox" name="includeMonthly" checked> Incluir a próxima mensalidade de ${money(s?.priceCents||0)}</label><p>Somente extras entregues e não faturados. O registro não emite boleto no banco.</p>`,d=>send({action,competence:d.get('competence'),dueDate:d.get('dueDate'),includeMonthly:d.get('includeMonthly')==='on'}));
  if(action==='approve_plan')return form('Aprovar planejamento','<p>As criações usarão o saldo disponível. Qualquer extra exige autorização separada.</p>'+confirm('Aprovo estes temas e datas.'),()=>send({action,id,confirmed:true}));
  await send({action,id});await load();toast('Solicitação registrada.');
 }catch(err){toast(err.message,true);}});
 document.addEventListener('change',async e=>{if(!active)return;try{if(e.target.id==='commerce-org'){org=e.target.value;await load();}if(e.target.id==='commerce-mode'){await send({action:'mode',mode:e.target.value});await load();}}catch(err){toast(err.message,true);}});
 return {page,mount(view){active=view==='commerce';++ticket;if(active)load();}};
}
